INSERT INTO "felirat" ("kulcs", "nyelv", "szoveg") VALUES
  ('nav.cegeim@fesztival', 'hu', 'Szervezeteim'),
  ('nav.cegeim@fesztival', 'ro', 'Organizațiile mele'),
  ('nav.cegeim@fesztival', 'en', 'My organisations'),
  ('beallitasok.mire_hasznalja_valasz@fesztival', 'hu', 'Arra, amit kérsz tőle: hírt értékel, szöveget ír, fordít, és megméri, összhangban van-e a fesztivál iránytűjével. A kiküldött szöveget nem tároljuk — az AI-kérésekről csak számok maradnak: melyik feladat, mennyi ideig tartott, mennyibe került.'),
  ('beallitasok.mire_hasznalja_valasz@fesztival', 'ro', 'La ceea ce îi ceri: evaluează știri, scrie text, traduce și verifică potrivirea cu busola festivalului. Textul trimis nu este stocat — despre cererile AI rămân doar cifre: ce sarcină, cât a durat, cât a costat.'),
  ('beallitasok.mire_hasznalja_valasz@fesztival', 'en', 'For what you ask of it: it rates news, writes text, translates, and checks the fit with the festival compass. The text sent out is not stored — only numbers remain about AI requests: which task, how long it took, what it cost.'),
  ('hf.fu_cegednek@fesztival', 'hu', 'A fesztiválnak'),
  ('hf.fu_cegednek@fesztival', 'ro', 'Pentru festival'),
  ('hf.fu_cegednek@fesztival', 'en', 'For your festival'),
  ('hf.profileTouch@fesztival', 'hu', 'Ez a közös profilt érintené (célközönség). A módosítást ott javasoljuk — a hírfigyelő nem írja át a fesztivál profilját.'),
  ('hf.profileTouch@fesztival', 'ro', 'Aceasta ar afecta profilul comun (publicul țintă). Recomandăm editarea acolo — modulul nu rescrie profilul festivalului.'),
  ('hf.profileTouch@fesztival', 'en', 'This would affect the shared profile (audience). We suggest editing it there — the monitor does not rewrite the festival profile.'),
  ('hf.rOther@fesztival', 'hu', 'Másik szervezet/személy'),
  ('hf.rOther@fesztival', 'ro', 'Altă organizație/persoană'),
  ('hf.rOther@fesztival', 'en', 'Different organisation/person'),
  ('hf.freePh@fesztival', 'hu', 'Pl. minden, ami a nyári fesztiválokat, a koncertjegyárakat és a kulturális pályázatokat érinti…'),
  ('hf.freePh@fesztival', 'ro', 'Ex. tot ce privește festivalurile de vară, prețurile biletelor la concerte și granturile culturale…'),
  ('hf.freePh@fesztival', 'en', 'e.g. everything about summer festivals, concert ticket prices and cultural grants…'),
  ('iranytu.cim@fesztival', 'hu', 'A fesztivál iránytűje'),
  ('iranytu.cim@fesztival', 'ro', 'Busola festivalului'),
  ('iranytu.cim@fesztival', 'en', 'Festival compass'),
  ('iranytu.ures_szoveg@fesztival', 'hu', 'A rendszer a fesztivál adataiból és a weboldalatokból javasol egy első változatot. Átírhatjátok, mielőtt jóváhagyjátok.'),
  ('iranytu.ures_szoveg@fesztival', 'ro', 'Sistemul sugerează o primă variantă din datele festivalului și din site-urile voastre. O puteți modifica înainte de a o aproba.'),
  ('iranytu.ures_szoveg@fesztival', 'en', 'The system suggests a first version from the festival''s details and your websites. You can edit it before approving.'),
  ('iranytu.vizio_sugo@fesztival', 'hu', 'Néhány mondat arról, hova tart a fesztivál.'),
  ('iranytu.vizio_sugo@fesztival', 'ro', 'Câteva propoziții despre unde se îndreaptă festivalul.'),
  ('iranytu.vizio_sugo@fesztival', 'en', 'A few sentences about where the festival is heading.'),
  ('kezdolap.elso_szoveg@fesztival', 'hu', 'Minden modul a közös profilból dolgozik: mit kínál a fesztivál, kinek, milyen céllal, milyen hangnemben. Amíg nincs jóváhagyott profil, a hírfigyelő nem tud értékelni.'),
  ('kezdolap.elso_szoveg@fesztival', 'ro', 'Toate modulele lucrează din profilul comun: ce oferă festivalul, pentru cine, cu ce scop, pe ce ton. Fără un profil aprobat monitorizarea nu poate evalua.'),
  ('kezdolap.elso_szoveg@fesztival', 'en', 'Every module works from the shared profile: what the festival offers, for whom, to what end, in what tone. Without an approved profile the news monitor cannot assess.'),
